SET CONSTRAINTS ALL DEFERRED;

-- D-037 / CB-16: the worker updates only profile, validation, suggestion and
-- error columns of imports, and only lease, status, attempt and error columns
-- of jobs; it can never commit an import.
SET LOCAL ROLE twin_worker;
UPDATE twin.imports SET status='PROFILING', total_rows=3, invalid_rows=0, preview='[{"row":1}]',
    mapping_suggestion_status='ready', mapping_suggestion='{"fields":[]}', validation='{"valid":true}', error=NULL
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000001';
SELECT pg_temp.must_fail(s, '42501') FROM unnest(ARRAY[
  $q$UPDATE twin.imports SET mapping='{"a":1}' WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.imports SET mapping_revision=mapping_revision+1 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.imports SET dataset_version_id=NULL WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.imports SET proposal_id=NULL WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.imports SET base_version_id='mv_01M4YDQK00TA00000000000001' WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.imports SET status='COMMITTED' WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.jobs SET payload='{"x":1}' WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='job_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.jobs SET priority=99 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='job_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.jobs SET max_attempts=10 WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='job_01M4YDQK00TA00000000000001'$q$,
  $q$UPDATE twin.jobs SET import_id=NULL, ai_proposal_id='aip_01M4YDQK00TA00000000000009' WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='job_01M4YDQK00TA00000000000001'$q$
]) AS s;
UPDATE twin.jobs SET status='running', attempt=attempt+1, locked_at=now(), locked_by='worker-1', lease_token=lease_token+1,
    lease_expires_at=now()+interval '30 seconds', heartbeat_at=now(), available_at=now(), error=NULL
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='job_01M4YDQK00TA00000000000001';
-- The API keeps the human-confirmed columns.
SET LOCAL ROLE twin_api;
UPDATE twin.imports SET mapping='{"fields":[]}', mapping_revision=mapping_revision+1
  WHERE organization_id='org_01M4YDQK00TA00000000000000' AND id='imp_01M4YDQK00TA00000000000001';

-- D-036 / CB-13: membership changes lock every owner membership of the
-- organization in user_id order; the API has no UPDATE (so no FOR UPDATE)
-- on organizations.
SELECT pg_temp.check((SELECT count(*) FROM (SELECT user_id FROM twin.memberships
    WHERE organization_id='org_01M4YDQK00TA00000000000000' AND role='owner' ORDER BY user_id FOR UPDATE) o) = 2,
  'the API locks the owner memberships');
SELECT pg_temp.must_fail($q$SELECT 1 FROM twin.organizations WHERE id='org_01M4YDQK00TA00000000000000' FOR UPDATE$q$, '42501');
SELECT pg_temp.check(NOT has_table_privilege('twin_api','twin.organizations','UPDATE'), 'no UPDATE grant on organizations');

-- TEST-011 (structural): FORCE RLS everywhere, runtime roles separate and
-- owning nothing, worker without identity, membership or idempotency access.
SET LOCAL ROLE twin_owner;
SELECT pg_temp.check(count(*)=0, 'tables without FORCE RLS or a policy: ' || coalesce(string_agg(c.relname, ', '), ''))
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='twin' AND c.relkind='r'
    AND (NOT c.relrowsecurity OR NOT c.relforcerowsecurity OR NOT EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid=c.oid));
SELECT pg_temp.check(count(*)=0, 'objects owned by a runtime role: ' || coalesce(string_agg(c.relname, ', '), ''))
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='twin' AND pg_get_userbyid(c.relowner) IN ('twin_api','twin_worker');
SELECT pg_temp.check(NOT pg_has_role(a, b, 'MEMBER'), format('%s must not be a member of %s', a, b))
  FROM (VALUES ('twin_api','twin_owner'),('twin_worker','twin_owner'),('twin_api','twin_worker'),('twin_worker','twin_api')) AS t(a, b);
SELECT pg_temp.check(NOT has_table_privilege('twin_worker', 'twin.' || t, p), format('worker has no %s on %s', p, t))
  FROM unnest(ARRAY['users','memberships','idempotency_keys','model_drafts']) AS t,
       unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE']) AS p;
SELECT pg_temp.check(count(*)=0, 'twin functions executable by PUBLIC: ' || coalesce(string_agg(p.proname, ', '), ''))
  FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
  WHERE n.nspname='twin' AND has_function_privilege('public', p.oid, 'EXECUTE');
SELECT pg_temp.check(NOT has_table_privilege('twin_worker', 'twin.' || t, 'INSERT'), format('worker cannot INSERT into %s', t))
  FROM unnest(ARRAY['model_versions','scenarios','model_version_datasets','imports','ai_proposals','simulation_runs']) AS t;

